{"id":"gen-1788835700-py6x3m9N1g3VMPGwiYi0","object":"chat.completion","created":1788835700,"model":"openai/gpt-6-astra-pro","provider":"OpenAI","system_fingerprint":null,"service_tier":"default","choices":[{"index":0,"logprobs":null,"finish_reason":"stop","native_finish_reason":"completed","message":{"role":"assistant","content":"{
